    "rest.compound": {
      "title": "Why this rest time?",
      "topic": "6. Rest intervals",
      "summary": "Resting longer between sets lets you lift more weight for more reps on the next set, so each set delivers more tension. Research shows a small growth advantage for resting more than about a minute, with little extra benefit beyond about 90 seconds to 2 minutes for most exercises. Isolation sets taken close to failure are just as demanding as big compound sets, so the same longer rest benefits every exercise.",
      "recommendation": "Rest 2–3 minutes between sets on every exercise, isolation work included. The longer rest is beneficial because it helps you match your previous set's weight and reps, which keeps every set productive.",
      "evidenceStrength": "Moderate to weak. In Singer 2024's analysis of 9 studies, the benefit of resting >60 s was small, results varied a lot between studies, and there was no clear gain beyond ~90 s. The most likely reason is that short rest cuts volume load. Longo 2022 supports this: once volume load was matched, rest length didn't matter. Saying that longer rest works \"through tension\" is a reasonable explanation, not something that was measured.",
      "citations": [
        {
          "authors": "Singer A, Wolf M, Generoso L, et al.",
          "year": 2024,
          "title": "Give it a rest: a systematic review with Bayesian meta-analysis on the effect of inter-set rest interval duration on muscle hypertrophy.",
          "journal": "Frontiers in Sports and Active Living",
          "doi": "10.3389/fspor.2024.1429789",
          "url": "https://doi.org/10.3389/fspor.2024.1429789",
          "pmid": "39205815"
        },
        {
          "authors": "Schoenfeld BJ, Pope ZK, Benik FM, et al.",
          "year": 2016,
          "title": "Longer Interset Rest Periods Enhance Muscle Strength and Hypertrophy in Resistance-Trained Men.",
          "journal": "Journal of Strength and Conditioning Research",
          "doi": "10.1519/JSC.0000000000001272",
          "url": "https://doi.org/10.1519/JSC.0000000000001272",
          "pmid": "26605807"
        },
        {
          "authors": "Longo AR, Silva-Batista C, Pedroso K, et al.",
          "year": 2022,
          "title": "Volume Load Rather Than Resting Interval Influences Muscle Hypertrophy During High-Intensity Resistance Training.",
          "journal": "Journal of Strength and Conditioning Research",
          "doi": "10.1519/JSC.0000000000003668",
          "url": "https://doi.org/10.1519/JSC.0000000000003668",
          "pmid": "35622106"
        }
      ],
      "status": "evidence",
      "source": "evidence.md §6"
    },
